import { LibraryError } from './errors.js';
import { readState, update } from './store.js';

function requireText(value, field) {
  if (typeof value !== 'string' || value.trim() === '') {
    throw new LibraryError(`${field} is required`);
  }
  return value.trim();
}

function requireCopies(value) {
  if (!Number.isInteger(value) || value < 1) {
    throw new LibraryError('copies must be a positive integer');
  }
  return value;
}

export function addBook({ title, author, copies = 1, data } = {}) {
  const cleanTitle = requireText(title, 'title');
  const cleanAuthor = requireText(author, 'author');
  const total = requireCopies(copies);
  return update(data, (state) => {
    const id = state.sequences.books + 1;
    state.sequences.books = id;
    const book = { id, title: cleanTitle, author: cleanAuthor, copies: total, available: total };
    state.books.push(book);
    return book;
  });
}

export function listBooks({ available, data } = {}) {
  const state = readState(data);
  let books = state.books.slice();
  if (available) books = books.filter((b) => b.available > 0);
  return books;
}
